interface.definition:
a!localVariables(
  local!newRoles: {},
  local!userRecord: index(
    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3070432"(
      userId: ri!userId,
      returnCDT: true,
      pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(
        startIndex: 1,
        batchSize: 1,
        sort: #"SYSTEM_SYSRULES_sortInfo"(field: "userId", ascending: true)
      )
    ),
    1,
    null
  ),
  local!isUserActive: isuseractive(ri!user),
  local!existingUserGroups: #"_a-0000ebac-bfa0-8000-9c55-011c48011c48_12959422"(ri!user),
  local!newGroupsList: local!existingUserGroups,
  local!rolesRecord: index(
    #"_a-0000ebac-bfa0-8000-9c55-011c48011c48_12951503"(userId: ri!userId),
    1,
    null
  ),
  {
    #"SYSTEM_SYSRULES_sectionLayout_v1"(label: "Edit User Role", ),
    if(
      toboolean(local!isUserActive),
      {
        #"SYSTEM_SYSRULES_sectionLayout_v1"(
          contents: {
            #"SYSTEM_SYSRULES_cardLayout"(
              padding: "MORE",
              showShadow: true,             
              contents: {
                #"SYSTEM_SYSRULES_columnsLayout"(
                  columns: {
                    #"SYSTEM_SYSRULES_columnLayout"(
                      width: "MEDIUM_PLUS",
                      contents: {
                        #"SYSTEM_SYSRULES_columnsLayout"(
                          columns: {
                            #"SYSTEM_SYSRULES_columnLayout"(width: "MEDIUM",
                              contents: {
                              #"SYSTEM_SYSRULES_richTextDisplayField"(
                                align: "RIGHT",
                                value:#"SYSTEM_SYSRULES_richTextItem_v1"(
                                  text: "User Name -",
                                  style: "STRONG",
                                  size: "MEDIUM",
                                  color: ""
                                ),
                              ),
                            }
                            ),
                            #"SYSTEM_SYSRULES_columnLayout"(width: "WIDE",
                            contents: {
                              #"SYSTEM_SYSRULES_richTextDisplayField"(
                                align: "LEFT",
                                value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                  text: local!userRecord.firstName&" "&local!userRecord.lastName,
                                  style: "STRONG",
                                  size: "MEDIUM",
                                  color: ""
                                ),
                              ),
                            }
                            ),
                            #"SYSTEM_SYSRULES_columnLayout"()
                          }
                        ),
                        #"SYSTEM_SYSRULES_columnsLayout"(
                          columns: {
                            #"SYSTEM_SYSRULES_columnLayout"(width: "MEDIUM",
                              contents: {
                                #"SYSTEM_SYSRULES_richTextDisplayField"(
                                  align: "RIGHT",
                                  value: {

                                    #"SYSTEM_SYSRULES_richTextItem_v1"(text: "DRT Status", style: "STRONG")
                                  }
                                )
                              }
                            ),
                            #"SYSTEM_SYSRULES_columnLayout"(width: "WIDE",
                              contents: {
                                #"SYSTEM_SYSRULES_richTextDisplayField"(
                                  align: "LEFT",
                                  labelPosition: "COLLAPSED",
                                  value:{ a!match(
                                    value: ri!newStatus,
                                    whenTrue: fv!value = true,
                                    then: #"SYSTEM_SYSRULES_richTextIcon"(
                                      icon: "toggle-on",
                                      size: "MEDIUM_PLUS",
                                      color: "POSITIVE",
                                      caption: "User status is active; click toggle to deactivate user",
                                      linkStyle: "STANDALONE",
                                      link: #"SYSTEM_SYSRULES_dynamicLink"(
                                        value: not(ri!newStatus),
                                        saveInto: {
                                          if(
                                            #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12219631"(ri!originalStatus),
                                            a!save(ri!originalStatus, ri!newStatus),
                                            {}
                                          ),
                                          ri!newStatus
                                        }
                                      )
                                    ),
                                    whenTrue: fv!value = false,
                                    then: #"SYSTEM_SYSRULES_richTextIcon"(
                                      icon: "toggle-off",
                                      size: "MEDIUM_PLUS",
                                      color: "NEGATIVE",
                                      caption: "User status is inactive; click toggle to activate user",
                                      linkStyle: "STANDALONE",
                                      link: #"SYSTEM_SYSRULES_dynamicLink"(
                                        value: not(ri!newStatus),
                                        saveInto: {
                                          if(
                                            #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12219631"(ri!originalStatus),
                                            a!save(ri!originalStatus, ri!newStatus),
                                            {}
                                          ),
                                          ri!newStatus
                                        }
                                      )
                                    ),
                                    default: #"SYSTEM_SYSRULES_richTextIcon"(icon: "toggle-off", size: "LARGE")
                                  )}
                                )
                              }
                            ),
                            #"SYSTEM_SYSRULES_columnLayout"()
                          }
                        )
                      }
                    ),
                    #"SYSTEM_SYSRULES_columnLayout"(),

                  }
                ),
                #"SYSTEM_SYSRULES_sectionLayout_v1"(
                  divider: "ABOVE",
                  contents: #"SYSTEM_SYSRULES_gridLayout"(
                    instructions: "Users having direct membership in the group can be removed using the icon. Indirect membership would be removed once user removed from sub-group",
                    label: "Groups and membership",
                    headerCells: {
                      #"SYSTEM_SYSRULES_gridLayoutHeaderCell"(label: "Group"),
                      #"SYSTEM_SYSRULES_gridLayoutHeaderCell"(label: "Member Type"),
                      #"SYSTEM_SYSRULES_gridLayoutHeaderCell"(label: "SubGroups"),
                      #"SYSTEM_SYSRULES_gridLayoutHeaderCell"(label: ""),

                    },
                    columnConfigs: {
                      #"SYSTEM_SYSRULES_gridLayoutColumnConfig"(width: "MEDIUM"),
                      #"SYSTEM_SYSRULES_gridLayoutColumnConfig"(width: "MEDIUM"),
                      #"SYSTEM_SYSRULES_gridLayoutColumnConfig"(width: "MEDIUM"),
                      #"SYSTEM_SYSRULES_gridLayoutColumnConfig"(width: "ICON")
                    },
                    rows: #"SYSTEM_SYSRULES_forEach"(
                      items: local!newGroupsList,
                      expression: {
                        #"SYSTEM_SYSRULES_gridRowLayout"(
                          contents: {
                            #"SYSTEM_SYSRULES_pickerFieldGroups"(disabled: true, value: fv!item,groupFilter: #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12219526"),
                            #"SYSTEM_SYSRULES_textField"(
                              readOnly: true,
                              value: 
                              if(
                                #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12219631"(fv!item),
                                "",
                                if(
                                  contains(
                                    touniformstring(
                                      a!groupMembers(
                                        group: fv!item,
                                        direct: true,
                                        memberType: "USER"
                                      ).data
                                    ),
                                    ri!user
                                  ),
                                  "Direct Member",
                                  "Indirect Member"
                                )
                              )

                            ),
                            #"SYSTEM_SYSRULES_textField"(
                              readOnly: true,
                              value: #"SYSTEM_SYSRULES_forEach"(
                                items: intersection(
                                  touniformstring(a!groupMembers(group: fv!item,direct: true, memberType: "GROUP").data),
                                  touniformstring(local!newGroupsList)
                                ),
                                expression: group(tointeger(fv!item),"groupName")
                              )
                            ),
                            #"SYSTEM_SYSRULES_richTextDisplayField"(
                              value: {
                                #"SYSTEM_SYSRULES_richTextIcon"(
                                  icon: "times",
                                  color: if(
                                    #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12219631"(fv!item),
                                    "STANDARD",
                                    if(
                                      contains(
                                        touniformstring(
                                          a!groupMembers(
                                            group: fv!item,
                                            direct: true,
                                            memberType: "USER"
                                          ).data
                                        ),
                                        ri!user
                                      ),
                                      "NEGATIVE",
                                      "STANDARD"
                                    )
                                  ),
                                  link: if(
                                    contains(
                                      touniformstring(
                                        a!groupMembers(
                                          group: fv!item,
                                          direct: true,
                                          memberType: "USER"
                                        ).data
                                      ),
                                      ri!user
                                    ),
                                    #"SYSTEM_SYSRULES_dynamicLink"(
                                      value: fv!index,
                                      saveInto: {
                                        a!save(
                                          local!newGroupsList,
                                          remove(local!newGroupsList, save!value)
                                        )
                                      }
                                    ),
                                    ""
                                  ),
                                  linkStyle: "STANDALONE",
                                  caption: if(
                                    contains(
                                      touniformstring(
                                        a!groupMembers(
                                          group: fv!item,
                                          direct: true,
                                          memberType: "USER"
                                        ).data
                                      ),
                                      ri!user
                                    ),
                                    "Remove user from the group",
                                    "Indirect members can't be removed from here"
                                  )
                                )
                              }
                            )
                          }
                        )
                      }
                    ),
                    borderStyle: "STANDARD",

                  )
                ),
                #"SYSTEM_SYSRULES_sectionLayout_v1"(
                  label: "",
                  contents: {
                    #"SYSTEM_SYSRULES_cardLayout"(
                      style:"STANDARD",
                      contents:{
                        #"SYSTEM_SYSRULES_columnsLayout"(
                          columns:{

                            #"SYSTEM_SYSRULES_columnLayout"(
                              width: "MEDIUM_PLUS",
                              contents:{
                                #"SYSTEM_SYSRULES_pickerFieldGroups"(
                                  label: "Add New Roles",
                                  /*required: ri!newStatus=true,*/
                                  groupFilter: #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12219526",
                                  value:local!newRoles,
                                  saveInto: {
                                    a!save(local!newRoles,save!value),
                                  },
                                  disabled: ri!newStatus=false
                                )
                              }
                            ),


                          }
                        )
                      }
                    )
                  }
                )
              }
            )
          }
        ),
        #"SYSTEM_SYSRULES_sectionLayout_v1"(),
        #"SYSTEM_SYSRULES_ButtonLayout"(
          primaryButtons: {
            #"SYSTEM_SYSRULES_buttonWidget_v1"(
              label: "UPDATE",
              submit: true,
              style: "SOLID",
              validate: true,
              value: "Update",
              saveInto: {
                ri!buttonValue,
                a!save(local!newGroupsList,append(local!newGroupsList,local!newRoles)),
                a!save(
                  ri!removeGroupsList,
                  difference(
                    togroup(local!existingUserGroups),
                    togroup(local!newGroupsList)
                  )
                ),
                a!save(
                  ri!addGroupsList,
                  difference(
                    togroup(local!newGroupsList),
                    togroup(local!existingUserGroups)
                  )
                ),
                a!save(
                  ri!userRecord,
                  #"urn:appian:function:v1:a:update"(
                    local!userRecord,
                    { "isActive", "modifiedBy", "modifiedOn" },
                    { ri!newStatus, loggedInUser(), now() }
                  )
                ),
                if(
                  #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12219631"(local!newGroupsList),
                  {},
                  a!save(
                    ri!newGroupNames,
                    getgroupnames(togroup(local!newGroupsList))
                  ),
                ),

                a!save(
                  ri!newGroupNames,
                  #"SYSTEM_SYSRULES_forEach"(
                    items: ri!newGroupNames,
                    expression: { trim(replace(fv!item, 1, 3, "")) }
                  )
                ),
                a!save(
                  local!rolesRecord,
                  #"urn:appian:function:v1:a:update"(
                    local!rolesRecord,
                    { "role", "appianstatus" },
                    {
                      joinarray(ri!newGroupNames, ";"),
                      if(isuseractive(ri!user), true, false)
                    }
                  )
                ),
                a!save(ri!rolesRecord, local!rolesRecord)
              },
              disabled: and(
                ri!originalStatus = false,
                ri!newStatus = false
              )
            )
          },
          secondaryButtons: {
            #"SYSTEM_SYSRULES_buttonWidget_v1"(
              label: "Cancel",
              submit: true,
              value: "Cancel",
              saveInto: ri!buttonValue,
              validate: false
            )
          }
        )
      },
      #"_a-0000ebac-bfa0-8000-9c55-011c48011c48_12942832"(
        buttonValue: ri!buttonValue,
        rolesRecord: ri!rolesRecord,
        rolesLocal: local!rolesRecord,
        userRecord: ri!userRecord,
        userRecordLocal: local!userRecord
      )
    )
  }
)
